node --input-type=module -e "
import { backoffDelay } from './src/retry.js';
for (const a of [0,1,2,3,6]) {
  const N=100000; let neg=0, min=Infinity, max=-Infinity;
  for (let i=0;i<N;i++){ const d=backoffDelay(a); if(d<=0)neg++; min=Math.min(min,d); max=Math.max(max,d); }
  console.log('attempt',a,'min',min.toFixed(0),'max',max.toFixed(0),'<=0:',(100*neg/N).toFixed(1)+'%');
}"
